const express = require('express');
const { requireFirebaseAuth } = require('../middleware/auth.middleware');
const { requireRole } = require('../middleware/role.middleware');
const {
  registerOrUpdateSellerProfile,
  getSellerProfile
} = require('../controllers/seller.controller');
const {
  createSellerProduct,
  getSellerProducts,
  getSellerProductById,
  updateSellerProduct,
  updateSellerProductStock
} = require('../controllers/product.controller');

const router = express.Router();

// Seller profile endpoints (Requires authenticated user)
router.post('/profile', requireFirebaseAuth, registerOrUpdateSellerProfile);
router.get('/profile', requireFirebaseAuth, getSellerProfile);

// Seller product management endpoints (Requires seller or admin role)
router.post('/products', requireFirebaseAuth, requireRole('seller', 'admin'), createSellerProduct);
router.get('/products', requireFirebaseAuth, requireRole('seller', 'admin'), getSellerProducts);
router.get('/products/:productId', requireFirebaseAuth, requireRole('seller', 'admin'), getSellerProductById);
router.patch('/products/:productId/stock', requireFirebaseAuth, requireRole('seller', 'admin'), updateSellerProductStock);
router.patch('/products/:productId', requireFirebaseAuth, requireRole('seller', 'admin'), updateSellerProduct);

module.exports = router;
